// Function to create and return a dynamically allocated square matrix of size N x N
double** createSquareMatrix(int N) {
    double **matrix;
    matrix = (double**)malloc(N * sizeof(double*));
    for(int i = 0; i < N; i++) {
        matrix[i] = (double*)malloc(N * sizeof(double));
    }
    return matrix;
}

// Function to print the square matrix
void printMatrix(double **matrix, int N) {
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            printf("%f ", matrix[i][j]);
        }
        printf("\n");
    }
}

// Function to free the dynamically allocated memory
void freeMatrix(double **matrix, int N) {
    for(int i = 0; i < N; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main() {
    int N;
    printf("Enter the size of the square matrix: ");
    scanf("%d", &N);

    double **matrix = createSquareMatrix(N);

    // Initialize the matrix with some values for demonstration (optional)
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            matrix[i][j] = i * N + j; // Example initialization
        }
    }

