```html
<script>
  // Set the initial time remaining for the timer to 7 days
  let timeRemaining1 = 7 * 24 * 60 * 60; // in seconds

  // Set the interval for the timer to update every second
  let timerInterval1 = setInterval(function() {
    // Decrement the time remaining by 1 second
    timeRemaining1--;

    // Get the timer element for the Orange Minimal Receiving Penalty Fee
    let timerElement1 = document.getElementById("timer1");

    // Update the timer element with the new time remaining
    timerElement1.innerHTML = formatTime(timeRemaining1);

    // If the time remaining is 0, update the fee amount and clear the interval
    if (timeRemaining1 === 0) {
      let feeElement1 = document.getElementsByTagName("td")[1];
      feeElement1.innerHTML = "$500";
      clearInterval(timerInterval1);
    }
  }, 1000);

  // Function to format the time remaining as "X days Y hours Z minutes"
  function formatTime(timeRemaining) {
    let days = Math.floor(timeRemaining / (24 * 60 * 60));
    let hours = Math.floor((timeRemaining % (24 * 60 * 60)) / (60 * 60));
    let minutes = Math.floor((timeRemaining % (60 * 60)) / 60);
    return days + " days " + hours + " hours " + minutes + " minutes remaining";
  }
