class Problem {
    // This method checks if a number can be expressed as the difference of two squares
    public static bool CanBeExpressedAsDifferenceOfSquares(long num) {
        // A number can be expressed as the difference of two squares if it is not of the form 4k+2
        return num % 4 != 2;
    }

    // This method calculates the total count of numbers within the range [start, end] that can be expressed as the difference of two squares
    public static long CountNumbersExpressibleAsDifferenceOfSquares(long start, long end) {
        long count = 0;
        for (long i = start; i <= end; i++) {
            if (CanBeExpressedAsDifferenceOfSquares(i)) {
                count++;
            }
        }
        return count;
    }

    // Example usage
    public static void Main(string[] args) {
        Console.WriteLine(CountNumbersExpressibleAsDifferenceOfSquares(1, 10)); // Example range [1, 10]
        Console.WriteLine(CountNumbersExpressibleAsDifferenceOfSquares(5, 15)); // Example range [5, 15]
    }
}
```

