    <h1>Smooth Background Color Transition</h1>
    <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nullam et magna in velit ultrices vulputate. Integer feugiat convallis enim, in pellentesque dolor pretium sit amet. Donec malesuada eleifend metus auctor varius. Morbi id sem nec ipsum pretium dapibus. Nullam facilisis ante in tellus cursus, et volutpat sem iaculis. Nullam euismod justo a erat consequat, et luctus orci placerat.</p>

    <script>
        function lerp(start, end, t) {
            return start * (1 - t) + end * t;
        }

        function hexToRgb(hex) {
            const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
            return result ? {
                r: parseInt(result[1], 16),
                g: parseInt(result[2], 16),
                b: parseInt(result[3], 16)
            } : null;
        }

        function animateBackground(startColor, endColor, duration) {
            let startTime = null;

            function step(timestamp) {
                if (!startTime) startTime = timestamp;
                const progress = timestamp - startTime;

                if (progress < duration) {
                    const t = progress / duration;
                    const currentColor = {
                        r: lerp(startColor.r, endColor.r, t),
                        g: lerp(startColor.g, endColor.g, t),
                        b: lerp(startColor.b, endColor.b, t)
                    };
                    document.body.style.backgroundColor = `rgb(${currentColor.r}, ${currentColor.g}, ${currentColor.b})`;
                    requestAnimationFrame(step);
                } else {
                    document.body.style.backgroundColor = endColor;
                }
            }

            requestAnimationFrame(step);
        }

        const startColor = hexToRgb("#0000FF"); // Blue
        const endColor = hexToRgb("#00FF00"); // Green
        const duration = 3000; // 3 seconds

        animateBackground(startColor, endColor, duration);
    </script>
