  if (typeof phoneNumber !== 'string' || phoneNumber.length !== 10 || !/^\d{10}$/.test(phoneNumber)) {
    throw new Error('Invalid phone number. Please provide a 10-digit number as a string.');
  }

  // Format the phone number
