Next, create a JavaScript file (e.g., `textAnimator.js`) to define the jQuery plugin:

```javascript
// textAnimator.js

(function($) {
  $.fn.textAnimator = function(options) {
    // Default options
    const settings = $.extend({
      animations: ['fadeIn', 'slideIn'],
      duration: 1000,
      delay: 2000
    }, options);

    // Initialize the plugin
    return this.each(function() {
      const $this = $(this);
      let currentTextIndex = 0;
      const $texts = $this.find('.text');
      const numTexts = $texts.length;

      function animateText() {
        const currentText = $texts.eq(currentTextIndex);
        currentText.addClass(settings.animations[currentTextIndex % settings.animations.length]);

        setTimeout(() => {
          currentText.removeClass(settings.animations[currentTextIndex % settings.animations.length]);
          currentTextIndex = (currentTextIndex + 1) % numTexts;
          animateText();
        }, settings.duration + settings.delay);
      }

      animateText();
    });
  };
}(jQuery));
```

Finally, use the plugin in your HTML file:

