  password: "hashedPassword1"
})
```

#### Posts Collection

```shell
db.posts.insert({
  title: "My First Post",
  content: "This is the content of my first post.",
  userRef: ObjectId("60a7c0e4f7f3e45c1f7f3e45") // Replace this with the actual ObjectId of the user
})
```

### Step 4: Define the Schema (Optional)

MongoDB is schema-less, but you can use Mongoose (a MongoDB object modeling tool designed to work in an asynchronous environment) or similar libraries to define a schema for your collections. Here's how you can define the schema using Mongoose:

```javascript
const mongoose = require('mongoose');
const Schema = mongoose.Schema;

const userSchema = new Schema({
  username: { type: String, required: true },
  email: { type: String, required: true },
  password: { type: String, required: true }
});

const postSchema = new Schema({
  title: { type: String, required: true },
  content: { type: String, required: true },
  userRef: { type: Schema.Types.ObjectId, ref: 'User', required: true }
});

const User = mongoose.model('User', userSchema);
const Post = mongoose.model('Post', postSchema);
```

### Step 5: Use the Database

Now you can use the `blogApp` database and its collections in your application. Remember to replace the `userRef` in the `posts` collection with the actual `_id` of the user from the `users` collection.

That's it! You've created a new MongoDB database for a blog application with collections for `users` and `posts`.

