```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cassert>

// Function to find the minimum amount of money required so that at least one friend
// receives an integer amount of money, given a list of percentages and a limit on
// the number of friends.
long find_min_money_for_integer_share(const std::vector<int>& percentages, int limit) {
    // Sort the percentages in descending order to prioritize higher percentages.
    std::vector<int> sorted_percentages = percentages;
    std::sort(sorted_percentages.begin(), sorted_percentages.end(), std::greater<int>());

    long min_money = 1; // Start with the minimum possible amount of money.
    // Iterate over the sorted percentages up to the limit.
    for (int i = 0; i < limit; ++i) {
        // Calculate the amount of money for the current percentage.
        long current_amount = min_money * sorted_percentages[i] / 100;
        // If the current amount is not an integer, increment the total money until it is.
        while (current_amount * 100 % sorted_percentages[i] != 0) {
            ++min_money;
            current_amount = min_money * sorted_percentages[i] / 100;
        }
    }
    return min_money;
}

// Check function to verify the correctness of the find_min_money_for_integer_share function.
void check_min_money_for_integer_share() {
    assert(find_min_money_for_integer_share({30, 20, 50}, 3) == 100);
    assert(find_min_money_for_integer_share({25, 50, 10, 15}, 2) == 100);
    assert(find_min_money_for_integer_share({1, 2, 3, 4, 5}, 1) == 100);
    assert(find_min_money_for_integer_share({100, 50, 25}, 2) == 100);
    std::cout << "All test cases passed!" << std::endl;
}

