std::vector<int> findIntersection(std::vector<int> array1, std::vector<int> array2) {
    std::vector<int> intersection;
    int i = 0, j = 0;
    while (i < array1.size() && j < array2.size()) {
        if (array1[i] == array2[j]) {
            // Avoid duplicates in the intersection array
            if (intersection.empty() || intersection.back() != array1[i]) {
                intersection.push_back(array1[i]);
            }
            i++;
            j++;
        } else if (array1[i] < array2[j]) {
            i++;
        } else {
            j++;
        }
    }
    return intersection;
}

