    /// </summary>
    /// <param name="x">The X coordinate of the point.</param>
    /// <param name="y">The Y coordinate of the point.</param>
    public Point(float x, float y)
    {
        X = x;
        Y = y;
    }

    /// <summary>
    /// Adds two Point objects and returns a new Point object.
    /// </summary>
    /// <param name="point1">The first point.</param>
    /// <param name="point2">The second point.</param>
    /// <returns>A new Point object that is the result of the addition.</returns>
    public static Point operator +(Point point1, Point point2)
    {
        return new Point(point1.X + point2.X, point1.Y + point2.Y);
    }

    /// <summary>
    /// Subtracts one Point object from another and returns a new Point object.
    /// </summary>
    /// <param name="point1">The first point.</param>
    /// <param name="point2">The second point.</param>
    /// <returns>A new Point object that is the result of the subtraction.</returns>
    public static Point operator -(Point point1, Point point2)
    {
        return new Point(point1.X - point2.X, point1.Y - point2.Y);
    }

    /// <summary>
    /// Determines whether two Point objects are equal.
    /// </summary>
    /// <param name="point1">The first point.</param>
    /// <param name="point2">The second point.</param>
    /// <returns>True if the points are equal; otherwise, false.</returns>
    public static bool operator ==(Point point1, Point point2)
    {
        return point1.X == point2.X && point1.Y == point2.Y;
    }

    /// <summary>
    /// Determines whether two Point objects are not equal.
    /// </summary>
    /// <param name="point1">The first point.</param>
    /// <param name="point2">The second point.</param>
    /// <returns>True if the points are not equal; otherwise, false.</returns>
    public static bool operator !=(Point point1, Point point2)
    {
        return point1.X != point2.X || point1.Y != point2.Y;
    }

    /// <summary>
    /// Calculates the Euclidean distance between two points.
    /// </summary>
    /// <param name="point1">The first point.</param>
    /// <param name="point2">The second point.</param>
    /// <returns>The distance between the two points.</returns>
    public static float Distance(Point point1, Point point2)
    {
        float dx = point1.X - point2.X;
        float dy = point1.Y - point2.Y;
        return (float)Math.Sqrt(dx * dx + dy * dy);
    }
}
```

This class represents a point in 2D space with floating point coordinates and provides methods to add, subtract, compare, and calculate the distance between two points. The class is robust against potential exceptions that might occur during the calculation, as the operations performed are simple arithmetic operations that do not throw exceptions under normal circumstances. The class also provides clear and descriptive documentation for each method and property.

