```java
import java.util.HashSet;
import java.util.Set;

public class UniquePairFinder {
    /**
     * Finds and returns all unique pairs of integers in the array that sum up to the target value.
     * The pair (a, b) is considered the same as (b, a) and should not be duplicated in the result.
     * 
     * Example:
     * Input array: [1, 3, 2, 2, 4, 0], target: 4
     * Output: [(0, 4), (1, 3), (2, 2)]
     * 
     * @param numbers The array of integers to search through.
     * @param target The target sum for the pairs.
     * @return A set of unique integer pairs that sum up to the target.
     */
    public static Set<Pair> findUniquePairs(int[] numbers, int target) {
        Set<Integer> seen = new HashSet<>();
        Set<Pair> pairs = new HashSet<>();
        for (int number : numbers) {
            int complement = target - number;
            if (seen.contains(complement)) {
                int smaller = Math.min(number, complement);
                int larger = Math.max(number, complement);
                pairs.add(new Pair(smaller, larger));
            }
            seen.add(number);
        }
        return pairs;
    }

    /**
     * A simple pair class to hold two integer values.
     */
    public static class Pair {
        private final int first;
        private final int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return first == pair.first && second == pair.second;
        }

        @Override
        public int hashCode() {
            return 31 * first + second;
        }

        @Override
        public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }

    public static void main(String[] args) {
        int[] numbers = {1, 3, 2, 2, 4, 0};
        int target = 4;
        Set<Pair> pairs = findUniquePairs(numbers, target);
        System.out.println(pairs);

        // Check function with provided data points
        check(new int[]{1, 3, 2, 2, 4, 0}, 4, new HashSet<>(Set.of(new Pair(0, 4), new Pair(1, 3), new Pair(2, 2))));
        check(new int[]{0, -1, 2, -3, 1}, -2, new HashSet<>(Set.of(new Pair(-3, 1))));
    }

    private static void check(int[] numbers, int target, Set<Pair> expected) {
        Set<Pair> result = findUniquePairs(numbers, target);
        assert result.equals(expected) : "Expected " + expected + ", but got " + result;
        System.out.println("Test passed.");
    }
}
```

This Java program defines a method `findUniquePairs` that takes an array of integers and a target sum as input and returns a set of unique pairs that sum up to the target. The `Pair` class is used to represent the pairs, and a `check` function is provided to verify the correctness of the solution with given test cases.

