increase_quantity <- function(fruit, amount) {
  if (fruit %in% fruit_basket$fruits) {
    if (amount >= 0) {
      fruit_basket$quantities[fruit_basket$fruits == fruit] <- 
        fruit_basket$quantities[fruit_basket$fruits == fruit] + amount
    } else {
      print("Error: The amount must be a non-negative number.")
    }
  } else {
    print("Error: The fruit is not in the basket.")
  }
}

# Function to determine the fruit with the highest quantity
highest_quantity_fruit <- function() {
  max_quantity <- max(fruit_basket$quantities)
  max_fruit <- fruit_basket$fruits[fruit_basket$quantities == max_quantity]
  return(max_fruit)
}

# Test the functions
increase_quantity('apple', 3)
increase_quantity('mango', -2)
increase_quantity('grape', 5)

print(fruit_basket)

max_fruit <- highest_quantity_fruit()
print(paste("The fruit with the highest quantity is:", max_fruit))
