To create a Node.js module for connecting to a MySQL database with the mentioned features, you can use the `mysql2` package. Below is an example of how you can create a module that includes a connection pool, query execution function, and transaction handling.

First, make sure you have `mysql2` package installed in your project by running `npm install mysql2`.

Create a new file named `db.js` and add the following code:

```javascript
const mysql = require('mysql2/promise');

class DB {
  constructor(poolConfig) {
    this.pool = mysql.createPool(poolConfig);
  }

  async query(sql, params = []) {
    const connection = await this.pool.getConnection();
    try {
      const [result] = await connection.query(sql, params);
      return result;
    } finally {
      connection.release();
    }
  }

  async beginTransaction() {
    const connection = await this.pool.getConnection();
    try {
      await connection.beginTransaction();
      return connection;
    } catch (error) {
      connection.release();
      throw error;
    }
  }

  async commit(connection) {
    try {
      await connection.commit();
    } finally {
      connection.release();
    }
  }

  async rollback(connection) {
    try {
      await connection.rollback();
    } finally {
      connection.release();
    }
  }
}

module.exports = DB;
```

Now you can use this module in your application like this:

```javascript
const DB = require('./db');

const poolConfig = {
  host: 'localhost',
  user: 'root',
  password: 'password',
  database: 'testdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
};

const db = new DB(poolConfig);

async function main() {
  try {
    const result = await db.query('SELECT * FROM users WHERE id = ?', [1]);
    console.log(result);

    const connection = await db.beginTransaction();
    try {
      await connection.query('INSERT INTO users (name) VALUES (?)', ['John Doe']);
      await db.commit(connection);
    } catch (error) {
      await db.rollback(connection);
      throw error;
    }
  } catch (error) {
    console.error(error);
  }
}

main();
```

This example demonstrates how to use the created module to query the database and handle transactions. Make sure to replace the `poolConfig` values with your actual database connection details.

