// Define a function to validate the input time string
function validateTime(timeString):
    // Check if the string matches the military time format
    if regex match(timeString, "\d\d:\d\d"):
        // Split the string into hours and minutes
        split timeString on ":" into hours and minutes
        hours = convert hours to integer
        minutes = convert minutes to integer
        // Check if the hours and minutes are within valid range
        if hours >= 0 and hours <= 23 and minutes >= 0 and minutes <= 59:
            return true
        else:
            return false
    else:
