// Define a function to convert a valid military time string to 12-hour clock format
function convertTime(timeString, outputFormat, timeZone):
    // Split the string into hours and minutes
    split timeString on ":" into hours and minutes
    hours = convert hours to integer
    minutes = convert minutes to integer
    // Convert the hours to 12-hour clock format
    if outputFormat == "12-hour clock":
        if hours >= 13:
            hours = hours - 12
            amPm = "PM"
        else if hours == 12:
            amPm = "PM"
        else:
            amPm = "AM"
        if hours == 0:
            hours = 12
        return concatenate(hours, ":", minutes, " ", amPm, " (", timeZone, ")")
    // Convert the hours to AM/PM format
    else if outputFormat == "AM/PM":
        if hours >= 13:
            hours = hours - 12
            amPm = "PM"
        else if hours == 12:
            amPm = "PM"
        else:
            amPm = "AM"
        if hours == 0:
            hours = 12
        return concatenate(hours, ":", minutes, " ", amPm, " (", timeZone, ")")
    // Return an error if the output format is not recognized
    else:
        return "Error: Output format not recognized"

// Define the main function to process an array of time strings
function processTimeArray(timeArray, outputFormat, timeZone):
    convertedTimeArray = new empty list
    for each timeString in timeArray:
        if validateTime(timeString):
            convertedTime = convertTime(timeString, outputFormat, timeZone)
            add convertedTime to convertedTimeArray
        else:
            add "Error: Invalid time format" to convertedTimeArray
    return convertedTimeArray
